//  DETERMINE POINT VALUE OF CURRENT SONG TOWARDS WEEKLY QUOTA
function determineSongValue(x) {
  if (userLvl9 == "true") {
    console.log("userLvl9 definitely equals 'true'.");
    switch (x) {
      case 1:
        return 12;
      case 2:
        return 15;
      case 3:
        return 20;
      case 4:
        return 30;
      case 5:
        return 60;
      case 6:
        return 60;
      case 7:
        return 60;
      case 8:
        return 60;
      case 9:
        return 120;
      default:
        return 180;
    }
  }

  if (handicap == 2) {
    switch (x) {
      case 1:
        return 30;
      default:
        return 60;
    }
  }

  switch (x) {
    case 1:
      return 15;
    case 2:
      return 20;
    case 3:
      return 30;
    case 4:
      return 60;
    case 5:
      return 60;
    case 6:
      return 60;
    case 7:
      return 60;
    case 8:
      return 120;
    case 9:
      return 120;
    default:
      return 180;
  }
}

